from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []
    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                _, wt = cache[key]
                if t - wt >= ttl:
                    # expired, remove
                    del cache[key]
            if key in cache:
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                val, wt = cache[key]
                if t - wt >= ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    results.append(val)
                    cache.move_to_end(key)
            else:
                results.append(-1)
    return results

